(async () => {
  const { existsSync } = await import('node:fs');
  const input = process.env.INPUT_PATH;
  const output = process.env.OUTPUT_PATH;
  if (!input) throw new Error('Missing INPUT_PATH');
  if (!output) throw new Error('Missing OUTPUT_PATH');
  if (!existsSync(input)) throw new Error('Input file does not exist: ' + input);
  globalThis.inputPath = input;
  globalThis.outputPath = output;
})();

(async () => {
  const fs = await import('node:fs');
  const { convert, sizes } = await import('image-to-pdf');
  const pages = [globalThis.inputPath];
  const stream = convert(pages, sizes.A4);
  await new Promise((resolve, reject) => {
    const out = fs.createWriteStream(globalThis.outputPath);
    stream.pipe(out);
    out.on('finish', resolve);
    out.on('error', reject);
  });
})();
